create or replace function public.provision_company(p_user_id uuid,p_company_name text,p_legal_name text default null) returns jsonb language plpgsql security definer set search_path=public as $$ declare c public.companies; s public.stores; b public.branches; begin insert into public.companies(name,legal_name,created_by) values(p_company_name,p_legal_name,p_user_id) returning * into c; insert into public.company_members(company_id,user_id,role_key,status) values(c.id,p_user_id,'owner','active'); insert into public.stores(company_id,name) values(c.id,'Main Store') returning * into s; insert into public.branches(company_id,store_id,name,code) values(c.id,s.id,'Main Branch','MAIN') returning * into b; insert into public.audit_logs(company_id,actor_user_id,action,resource_type,resource_id,metadata) values(c.id,p_user_id,'auth.register','company',c.id,jsonb_build_object('provisioned',true)); return jsonb_build_object('company',to_jsonb(c),'store',to_jsonb(s),'branch',to_jsonb(b)); exception when others then raise; end; $$;